import { CircleNotch, WarningCircle } from "@phosphor-icons/react";

export function LedgerTable({ caption, columns, rows, state = "default", onRetry, onRowActivate }) {
  const displayRows = state === "loading" ? Array.from({ length: 4 }, (_, index) => ({ id: `loading-${index}` })) : rows;
  return <div className="ml-table-frame" data-state={state}>{state === "error" ? <div className="ml-table__message"><WarningCircle size={18} weight="fill" /><span><strong>数据读取失败</strong><small>保留了上一版列结构。</small></span><button type="button" className="ml-table__retry" onClick={onRetry}><CircleNotch size={14} />重试</button></div> : <table className="ml-table"><caption>{caption}</caption><thead><tr>{columns.map((column) => <th key={column.key} data-align={column.align || "start"}>{column.label}</th>)}</tr></thead><tbody>{displayRows.length ? displayRows.map((row, index) => state === "loading" ? <tr key={row.id} className="ml-table__skeleton-row">{columns.map((column) => <td key={column.key}><span /></td>)}</tr> : <tr key={row.id || index} tabIndex={0} aria-disabled={row.disabled} data-state={row.state} onClick={() => !row.disabled && onRowActivate?.(row)} onKeyDown={(event) => { if ((event.key === "Enter" || event.key === " ") && !row.disabled) onRowActivate?.(row); }}>{columns.map((column) => <td key={column.key} data-align={column.align || "start"}>{column.render ? column.render(row[column.key], row) : row[column.key]}</td>)}</tr>) : <tr><td colSpan={columns.length} className="ml-table__empty">暂无符合条件的记录</td></tr>}</tbody></table>}</div>;
}

