export function LedgerDataTable({
  rows,
  columns,
  caption = "数据列表",
  pageSize = 5,
  showToolbar = true,
  selectable = true,
  selection,
  onSelectionChange,
  onRowActivate,
  onBulkAction,
  loading = false,
  disabled = false,
  error,
  onRetry
}) {
  const [query, setQuery] = useState(""),
    [sort, setSort] = useState(null),
    [page, setPage] = useState(1),
    [hidden, setHidden] = useState([]),
    [localSelection, setLocalSelection] = useState([]);
  const selected = (selection ?? localSelection).filter(id => rows.some(r => r.id === id && !r.disabled)),
    inert = loading || disabled;
